vec3 spectralZucconi6(float x) {
	const vec3 c1 = vec3(3.54585104, 2.93225262, 2.41593945);
	const vec3 x1 = vec3(0.69549072, 0.49228336, 0.27699880);
	const vec3 y1 = vec3(0.02312639, 0.15225084, 0.52607955);

	const vec3 c2 = vec3(3.90307140, 3.21182957, 3.96587128);
	const vec3 x2 = vec3(0.11748627, 0.86755042, 0.66077860);
	const vec3 y2 = vec3(0.84897130, 0.88445281, 0.73949448);

	vec3 col =  bump3y(c1 * (x - x1), y1) + bump3y(c2 * (x - x2), y2);
    col = invGamma(col);
    return col;
}

float rect( vec2 p, vec2 b, float r ) {
    vec2 d = abs(p) - (b - r);
    return length(max(d, 0.)) + min(max(d.x, d.y), 0.) - r;
}

// wrapped map
vec3 wrappedSpectralZucconi6(float x) {
    x = fract(x);
    return spectralZucconi6(x);
}

vec3 waveZucconi6(float w){

    if(w > 700.0 || w < 400.0){
        return vec3(0);
    }

	float x = fract((w - 400.0)/ 300.0);

    return spectralZucconi6(x);
}

// Get orthonormal basis from surface normal
// https://graphics.pixar.com/library/OrthonormalB/paper.pdf
void pixarONB(vec3 n, out vec3 b1, out vec3 b2){
	float sign_ = sign(n.z);
	float a = -1.0 / (sign_ + n.z);
	float b = n.x * n.y * a;
	b1 = vec3(1.0 + sign_ * n.x * n.x * a, sign_ * b, -sign_ * n.x);
	b2 = vec3(b, sign_ + n.y * n.y * a, -n.y);
}

vec3 diffraction(vec3 rd, vec3 n, vec3 td, vec3 l, float d) {

    vec3 col = vec3(0);

    float cos_ThetaL = dot(l, td);
    float cos_ThetaV = dot(rd, td);

    float u = abs(cos_ThetaL - cos_ThetaV);

    if(u == 0.) {
        return vec3(0);
    }

    for(float i=1.; i < 2.; i++) {
        float wavelength = u * d / i;
        col += waveZucconi6(wavelength);
    }
    col = clamp(col, vec3(0), vec3(1));
    return col;
}

// iq
float sdBoxFrame( vec3 p, vec3 b, float e ){

  p = abs(p  )-b;
  vec3 q = abs(p+e)-e;
  return min(min(
      length(max(vec3(p.x,q.y,q.z),0.0))+min(max(p.x,max(q.y,q.z)),0.0),
      length(max(vec3(q.x,p.y,q.z),0.0))+min(max(q.x,max(p.y,q.z)),0.0)),
      length(max(vec3(q.x,q.y,p.z),0.0))+min(max(q.x,max(q.y,p.z)),0.0));
}


float box(vec3 p, vec3 r) {
  vec3 d = abs(p) - r;
  return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}


vec3 transform(vec3 p) {
   p.z -= 5.;
   p.yz *= rot(.303*PI);
   p.yx *= rot(PI*.25 );
   return p;
}


// adapted from https://www.shadertoy.com/view/4sjXW1
vec2 cubeUV(in vec3 p) {
    vec2 x = p.zy/p.x;
    vec2 y = p.xz/p.y;
    vec2 z = p.xy/p.z;

    //select face
    p = abs(p);
    if (p.x > p.y && p.x > p.z) return x;
    else if (p.y > p.x && p.y > p.z) return y;
    else return z;
}

float map(vec3 p) {     

    vec3 bp = p;
    float edge = 0.04;

    p = transform(p);

    vec3 p1 = abs(p)- mix(.0, 2., SIN(0.5*tt));
    float f1 = sdBoxFrame(p1, vec3(1.0), .15)-edge;
  //  f1 = box(p1, vec3(1)) - edge;

    vec3 p2 = p1;

    float move = 5.*SIN(tt);
    mat2 mr = rot(1.*PI*S(.4, .9, SIN(tt)));
    p2.y -= move;
    p2.xy *= mr;

    float f2 = box(p2, vec3(.4)) - edge;
    p2 = p1;
    p2.x -= move;
    p2.xy *= mr;
    f2 = min(f2, box(p2, vec3(.4)) - edge);
    p2 = p1;
    p2.z -= move;
    p2.xy *= mr;
    f2 = min(f2, box(p2, vec3(.4)) - edge);

    g_uv = cubeUV(p1);

    g_mat = f1 < f2 ? 0. : 1.;
    float d = min(f1, f2); 
    //d = f1;
    return d;
}


vec3 getNormal(vec3 p) {

    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(map(p + eps.xyy) - map(p - eps.xyy),
                          map(p + eps.yxy) - map(p - eps.yxy),
                          map(p + eps.yyx) - map(p - eps.yyx)
                         )
                     );
}

// from iq code
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<1; i++ )
    {
		float h = map( ro + rd*t );
        res = min( res, 8.0*h/t );
        t += h*.25;
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0., 1. );
}

ObjectInfo raymarch(vec3 ro, vec3 rd, float steps) {

    float mat = 0.,
          t   = 0.,
          d   = 0.;

    vec2 uv; // object uv

    vec3 p = ro;
    for(float i=.0; i<steps; i++) {

        d = map(p);
        mat = g_mat;  // save global material infos
        uv = g_uv;

        if(abs(d) < 0.0001 || t > 100.) break;

        t += d;
        p += rd*d;
    }

    return ObjectInfo(t, mat, uv);  
}

float calcAO(vec3 p, vec3 n)
{
	float sca = 2.0, occ = 0.0;
    for( int i=0; i<5; i++ ){

        float hr = 0.01 + float(i)*0.5/4.0;        
        float dd = map(n * hr + p);
        occ += (hr - dd)*sca;
        sca *= 0.7;
    }
    return clamp( 1.0 - occ, 0.0, 1.0 );    
}

vec4 subsurface(vec3 o, vec3 dir){
    vec3 p = o;
    float e = 0.0;
    for(int i = 0; i < 7; ++i){
        float d = map(p);
        e += -d;
        if(d > -0.001)
            break;
        p -= d*dir;
    }

    return vec4(p, e);
}

