vec3 getColorRamp(int palette, float x) {

    x = fract(x);
    vec3 colors[10];
    int len;


    if(palette == 0) {
        len = colors1.length();
        COPY_COLOR(len, colors1);       
    }

    if(palette == 1) {
        len = colors2.length();
        COPY_COLOR(len, colors2);
    }
    if(palette == 2) {
        len = colors3.length();
        COPY_COLOR(len, colors3);

    }
    if(palette == 3) {
        len = colors4.length();
        COPY_COLOR(len, colors4);    
    }

    if(palette == 4) {
        len = colors5.length();
        COPY_COLOR(len, colors5);    
    }
    if(palette == 5) {
        len = colors6.length();
        COPY_COLOR(len, colors6);    
    }
    if(palette == 6) {
        len = colors7.length();
        COPY_COLOR(len, colors7);    
    }
    if(palette == 7) {
        return mix(vec3(0), vec3(1), smoothstep(0., 1., .5+.5*sin(5.*x)));

    }

    int colorCount = 5;
    float stepSize = 1.0/float(colorCount);
    // from MadMapper gradient
    int stepId = int(x/stepSize);
    vec3 col = mix(colors[stepId%colorCount],colors[(stepId+1)%colorCount],pow(x/stepSize-float(stepId),pow(1.0,6.)));
    return col;
   // return getColorRamp_(colors, len, x);

}


vec3 getPal(int pal, float x) {

    return getColorRamp(pal, x);
    // Wrap x to the 0-1 range
    float wrappedX = fract(x);

    // Determine the blend factor for the wrap-around edge
    float blendFactor = smoothstep(0.7, 1.3, x);

    // Get colors from the ramp
    vec3 currentColor = getColorRamp(pal, wrappedX);
    vec3 nextColor = getColorRamp(pal, fract(wrappedX + 0.3));

    // Blend the colors smoothly
    return mix(currentColor, nextColor, blendFactor);

    return currentColor;
}



float smoothNoise21(vec2 p) {
    // Calculate integer and fractional coordinates
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Compute gradients at the four corners of the cell
    float n00 = dot(vec2(cos(dot(i, vec2(127.1, 311.7))), sin(dot(i, vec2(127.1, 311.7)))), f - vec2(0.0, 0.0));
    float n01 = dot(vec2(cos(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))), sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7)))), f - vec2(0.0, 1.0));
    float n10 = dot(vec2(cos(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))), sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7)))), f - vec2(1.0, 0.0));
    float n11 = dot(vec2(cos(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))), sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7)))), f - vec2(1.0, 1.0));

    // Smooth interpolation using Hermite curve (smoothstep)
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Bilinear interpolation with gradients
    return mix(mix(n00, n10, u.x), mix(n01, n11, u.x), u.y);
}
